/**
 * Picklist OPTIONS — the `[{label, color?, tags}, …]` shape shared by field
 * `options` attributes and the app's `status_options` (the status system
 * field is a picklist wearing an app attribute). Both directions live here:
 * the wire→tf label projection and the tf→normalized-options extraction.
 */
import { plainObject } from "../../engine/pull/context.js";
import { withUniqueKeys } from "../../../pull/util.js";
export function picklistLabel(pv) {
    return pv.label ?? pv.value ?? "";
}
export const KNOWN_OPTION_TAGS = new Set([
    "CLOSED",
    "CRITICAL",
    "HIGH",
    "MEDIUM",
    "LOW",
]);
/**
 * A `[{label, tags?}, ...]` attribute (status_options, dropdown options) →
 * the keyed `options` record the normalized `AppField` carries. Keys derive
 * from labels via `withUniqueKeys` — they never print (the printer emits
 * labels), so they only need to be unique. Unknown tags drop with a
 * diagnostic; option ids stay empty (identity lives in terraform state).
 */
export function optionsFromTf(v, where, ctx) {
    if (v === undefined)
        return undefined;
    if (!Array.isArray(v)) {
        ctx.diagnostics.push(`${where}: expected a list; dropped`);
        return undefined;
    }
    const parsed = [];
    for (const item of v) {
        const rec = plainObject(item);
        const optLabel = typeof rec?.["label"] === "string" ? rec["label"] : undefined;
        if (rec === undefined || optLabel === undefined) {
            ctx.diagnostics.push(`${where}: option item has an unrecognized shape; dropped`);
            continue;
        }
        for (const key of Object.keys(rec)) {
            if (key !== "label" && key !== "tags" && key !== "color" && key !== "icon" && key !== "active" && key !== "parent_value_ids") {
                ctx.diagnostics.push(`${where}: option "${optLabel}" has an unhandled property "${key}"; dropped`);
            }
        }
        const color = typeof rec["color"] === "string" && rec["color"] !== "" ? rec["color"] : undefined;
        const icon = typeof rec["icon"] === "string" && rec["icon"] !== "" ? rec["icon"] : undefined;
        const active = typeof rec["active"] === "boolean" ? rec["active"] : undefined;
        const tags = [];
        const rawTags = rec["tags"];
        if (Array.isArray(rawTags)) {
            for (const t of rawTags) {
                if (typeof t === "string" && KNOWN_OPTION_TAGS.has(t)) {
                    tags.push(t);
                }
                else {
                    ctx.diagnostics.push(`${where}: option "${optLabel}" has an unknown tag ${JSON.stringify(t)}; dropped`);
                }
            }
        }
        else if (rawTags !== undefined) {
            ctx.diagnostics.push(`${where}: option "${optLabel}" tags is not a list; dropped`);
        }
        parsed.push({
            label: optLabel,
            ...(color !== undefined && { color }),
            ...(icon !== undefined && { icon }),
            ...(active !== undefined && { active }),
            tags,
        });
    }
    if (parsed.length === 0)
        return undefined;
    const out = {};
    for (const { key, item } of withUniqueKeys(parsed, (p) => p.label, "option")) {
        out[key] = {
            id: "",
            label: item.label,
            ...(item.color !== undefined && { color: item.color }),
            ...(item.icon !== undefined && { icon: item.icon }),
            ...(item.active !== undefined && { active: item.active }),
            ...(item.tags.length > 0 && { tags: item.tags }),
        };
    }
    return out;
}
